// Widescreen and the field of view in the driving levels.
//
// Every view is built by 0x102990 (thiscall: horizontal field of view in degrees, aspect, near, far), as NightFire's 0xE46D0,
// called from 0x846B0 (the game's views: twice the camera's half angle, aspect 4:3) and 0x7C530 (an auxiliary view, aspect 1,
// left alone). A wider frame widens the horizontal angle in tangent and the aspect with it: the vertical angle is the game's,
// and the cull data the view keeps follows from the same arguments. The field of view scales the angle first.
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstring>

#include "common/auf.h"
#include "gpu/state.h"
#include "kernel/kernel.h"
#include "vr/vr.h"
#include "xdk/d3d8.h"
#include "xdk/hle.h"

namespace {
constexpr float kPi = 3.14159265f;
float GetF(uint32_t va) {
    float f;
    std::memcpy(&f, &kernel::G<uint32_t>(va), 4);
    return f;
}
void SetF(uint32_t va, float f) { std::memcpy(&kernel::G<uint32_t>(va), &f, 4); }
}  // namespace

// The radar 0xB9010 draws in its own viewport. Its road map is a quad larger than that, so as it turns it can cover the viewport,
// and on a wide screen the renderers take such a draw for a pass filling its viewport and leave it unsqueezed where the disc and
// dots are squeezed: cut off by the viewport, the lines mostly gone. The whole radar is squeezed as one.
X86_EXTERN_FUNC(__imp__sub_000B9050);
X86_FUNC(sub_000B9050) {
    gpu::State& state = d3d::State();
    const bool was = state.squeeze_beyond;
    state.squeeze_beyond = true;
    __imp__sub_000B9050(ctx, base);
    state.squeeze_beyond = was;
}

// The fade on leaving a mission (0xB7B60) stops drawing and darkens whatever is in the back buffer with a black quad, each
// frame. Triple buffered, those are the last three frames, one without the pause menu and one half drawn, and it shows them in
// turn: the menu flickered through the fade. Each step now starts from the picture on screen, so the steps add up: the quad's
// brightness (0xBDD20's argument) becomes the step from the last one, which keeps the game's fade to black over the same time.
namespace {
X86_EXTERN_FUNC(sub_00114D60);
X86_EXTERN_FUNC(sub_00114DA0);
uint32_t BackBuffer(X86Context& ctx, uint8_t* base, int32_t which) {
    ctx.esp -= 4;
    const uint32_t out = ctx.esp;
    X86_PUSH32(out);
    X86_PUSH32(0);
    X86_PUSH32(uint32_t(which));
    X86_PUSH32(0);
    sub_00114D60(ctx, base);
    const uint32_t surface = kernel::G<uint32_t>(out);
    ctx.esp += 4;
    kernel::G<uint32_t>(surface) -= 1;  // GetBackBuffer's reference
    return surface;
}
// the buffers as the runtime's Swap leaves them: 0 is the one to draw, 1 the picture on screen (its memory rotates), -1 the oldest
void CopyBuffer(X86Context& ctx, uint8_t* base, uint32_t from, uint32_t to) {
    X86_PUSH32(0);
    X86_PUSH32(to);
    X86_PUSH32(0);
    X86_PUSH32(0);
    X86_PUSH32(from);
    X86_PUSH32(0);
    sub_00114DA0(ctx, base);
}
float g_fade_last = 0;  // brightness of the last step, 0 outside the fade
}  // namespace

X86_EXTERN_FUNC(__imp__sub_000B7BA0);
X86_FUNC(sub_000B7BA0) {
    g_fade_last = 1;
    __imp__sub_000B7BA0(ctx, base);
    g_fade_last = 0;
    // the buffers still holding the menu would show until the loading picture: all dark now
    const uint32_t shown = BackBuffer(ctx, base, 1);
    CopyBuffer(ctx, base, shown, BackBuffer(ctx, base, 0));
    CopyBuffer(ctx, base, shown, BackBuffer(ctx, base, -1));
}

X86_EXTERN_FUNC(__imp__sub_000BDBB0);
X86_FUNC(sub_000BDBB0) {
    if (g_fade_last > 0) {
        const uint32_t brightness = ctx.esp + 4;
        const float now = kernel::G<float>(brightness);
        CopyBuffer(ctx, base, BackBuffer(ctx, base, 1), BackBuffer(ctx, base, 0));
        kernel::G<float>(brightness) = std::clamp(now / g_fade_last, 0.0f, 1.0f);
        g_fade_last = std::max(now, 1.0f / 256);
    }
    __imp__sub_000BDBB0(ctx, base);
}

X86_EXTERN_FUNC(__imp__sub_00102400);
X86_FUNC(sub_00102400) {
    float aspect = GetF(ctx.esp + 8);
    if (aspect > 1.2f) {  // the game's views, not the auxiliary one
        auf::FrameCamera(ctx, base);  // a headset: this frame's camera, the game having moved it
        float k = auf::FrameWidth(), fov = GetF(ctx.esp + 4) * auf::FovScale();
        if (k > 1.0f + 1e-3f) {
            fov = 2 * std::atan(k * std::tan(fov * kPi / 360)) * 180 / kPi;
            SetF(ctx.esp + 8, aspect * k);
        }
        // a headset: 100 degrees upright in place of the game's 52 (66 across at 4:3), by the tangent, so its own zooms keep
        // their proportion
        if (vr::Enabled()) fov = 2 * std::atan(std::tan(50 * kPi / 180) / std::tan(25.96f * kPi / 180) * std::tan(fov * kPi / 360)) * 180 / kPi;
        SetF(ctx.esp + 4, std::min(fov, 170.0f));
    }
    __imp__sub_00102400(ctx, base);
}

// What the world draws is chosen apart from the view above: the list builder 0x7DC10 tests each thing's sphere against the frustum
// at 0x190640, whose planes 0x7B7F0 builds through 0x7E3C0 (thiscall: position, camera, half angle in degrees, far) from the camera's
// half angle alone, 33 degrees whatever the view's width (draw counts did not change at all from 4:3 to four times that). Given the
// wider angle here; it also reaches past the frame's edges by EoN's margin (2.2 times the tangent, Harry confirmed it there):
// on the edge, what stands just off the screen and lights what is on it popped as the car turned.
X86_EXTERN_FUNC(__imp__sub_0007E240);
X86_FUNC(sub_0007E240) {
    constexpr float kCullMargin = 2.2f, kMost = 80.0f;
    float half = GetF(ctx.esp + 0xC) * auf::FovScale();
    float wide = std::atan(std::max(auf::FrameWidth(), 1.0f) * kCullMargin * std::tan(half * kPi / 180)) * 180 / kPi;
    SetF(ctx.esp + 0xC, vr::Enabled() ? kMost : std::min(wide, kMost));  // a headset looks about: as wide as it goes
    __imp__sub_0007E240(ctx, base);
}

// The loading picture: 0xBDEC0 copies it into the back buffer by CPU, so the 2D squeeze never sees it
// and the frame's widening stretches it. Each row is shrunk into the frame's 4:3 middle, before the unlock
// (0xBDF75: [esp+0x1C] the rows, the locked rectangle's pitch [esp+0x20] and bits [esp+0x24]; a row is the pitch's width).
void LoadingPictureCentred(X86Context& ctx, uint8_t*) {
    const float k = auf::FrameWidth();
    if (k <= 1.001f) return;
    const uint32_t rows = kernel::R32(ctx.esp + 0x1C), pitch = kernel::R32(ctx.esp + 0x20), bits = kernel::R32(ctx.esp + 0x24);
    const uint32_t w = pitch / 4, n = uint32_t(float(w) / k), left = (w - n) / 2;
    if (!bits || !w || !n) return;
    std::vector<uint32_t> row(w);
    for (uint32_t y = 0; y < rows; y++) {
        auto* p = reinterpret_cast<uint32_t*>(&kernel::G<uint8_t>(bits + y * pitch));
        std::memcpy(row.data(), p, w * 4);
        // the row's edge colours out to the sides, as the on-foot screens' reach them
        for (uint32_t x = 0; x < w; x++) p[x] = x < left ? row[0] : x >= left + n ? row[w - 1] : row[size_t(x - left) * w / n];
    }
}
